  final DeadlineLadder ladder;

  int? _deadlineEpochMs;
  int _armedAtEpochMs = 0;
  final Set<DeadlineNoticeKind> _fired = <DeadlineNoticeKind>{};

  /// Whether a deadline is currently armed.
