  if (cancelToken == null) {
    return responseFuture.timeout(
      effectiveConnect,
      onTimeout: watchdogTimedOut,
    );
  }
  return Future.any([
    responseFuture,
    cancelToken.onCancel.then<http.StreamedResponse>(
      (_) => throw const AbortedError(),
    ),
