            .listen((_) {}, onError: (Object _) {}, cancelOnError: true)
            .cancel();
      }, onError: (Object _) {}),
    );
    // Issue #1554: a request-scoped override names itself on the stall
    // line so a widened (or narrowed) connect window never reads as the
