import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import '../cli/agent_cli_test_support.dart';

/// The transient-network retry wrapper: a Wi-Fi switch kills the stream
/// with "Connection reset by peer" — the call sleeps 5s and replays.
void main() {
  late Future<bool> Function(Duration, CancelToken?) savedSleeper;
  late TransientRetryNotice? savedNotice;
  late bool savedBufferThinking;

  setUp(() {
    savedSleeper = transientRetrySleeper;
    savedNotice = transientRetryNotice;
    savedBufferThinking = transientRetryBufferThinking;
    transientRetrySleeper = (delay, token) async => true;
    transientRetryNotice = null;
  });
  tearDown(() {
    transientRetrySleeper = savedSleeper;
    transientRetryNotice = savedNotice;
    transientRetryBufferThinking = savedBufferThinking;
  });

  group('isTransientNetworkError', () {
    AssistantMessage errorMsg(String text) => AssistantMessage(
      content: const [],
      api: 'test-api',
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.error,
      errorMessage: text,
      timestamp: DateTime.utc(2026),
    );

    test('matches the socket-level wordings', () {
      expect(
        isTransientNetworkError(
          errorMsg('SocketException: Connection reset by peer'),
        ),
        isTrue,
      );
      expect(isTransientNetworkError(errorMsg('Connection refused')), isTrue);
      expect(
        isTransientNetworkError(errorMsg('Network is unreachable')),
        isTrue,
      );
      expect(isTransientNetworkError(errorMsg('Connection timed out')), isTrue);
      expect(isTransientNetworkError(errorMsg('Broken pipe')), isTrue);
    });

    test('rejects non-transient failures', () {
      expect(isTransientNetworkError(errorMsg('401 unauthorized')), isFalse);
      expect(isTransientNetworkError(errorMsg('429 rate limit')), isFalse);
      expect(
        isTransientNetworkError(errorMsg('context length exceeded')),
        isFalse,
      );
      // A bad certificate never heals in 5 seconds.
      expect(
        isTransientNetworkError(
          errorMsg('HandshakeException: certificate verify failed'),
        ),
        isFalse,
      );
      // The idle watchdog's wording is not a socket error.
      expect(
        isTransientNetworkError(
          errorMsg(
            'no events from the endpoint for 300s (stream idle timeout)',
          ),
        ),
        isFalse,
      );
    });

    test('a cut stream (no finish_reason) is transport (issue #312)', () {
      expect(
        isTransientNetworkError(
          errorMsg(
            'stream ended without finish_reason — the reply may be truncated',
          ),
        ),
        isTrue,
      );
    });

    test('budget/spending exhaustion is never transient (issue #926)', () {
      expect(
        isTransientNetworkError(
          errorMsg(
            '403: CodeMie monthly budget limit reached (\$150.08 / \$150.00)',
          ),
        ),
        isFalse,
      );
      // A gateway-wrapped budget error quotes transport words — the budget
      // check must win, or the wrapper re-arms the loop the issue reports.
      expect(
        isTransientNetworkError(
          errorMsg(
            '500: Internal network failure — spending limit reached, '
            'please try again later',
          ),
        ),
        isFalse,
      );
    });
  });

  group('transientRetryStreamFunction', () {
    AssistantMessageEventStream failWith(String text) {
      final stream = AssistantMessageEventStream();
      scheduleMicrotask(() {
        stream.push(
          ErrorEvent(

    errorType: text('type'),
    planType: text('plan_type'),
    eligiblePromo: text('eligible_promo'),
    resetsInSeconds: intOf('resets_in_seconds'),
    resetsAt: resetsAtUnix is int && resetsAtUnix > 0
        ? DateTime.fromMillisecondsSinceEpoch(resetsAtUnix * 1000, isUtc: true)
        : null,
    limitKind: limitKind,
    retryAfter: parseRetryAfter(_header(headers, 'retry-after'), now: now),
    rawBody: body,
  );
}

/// Case-insensitive header lookup (header casing varies by hop).
String? _header(Map<String, String> headers, String name) {
  for (final entry in headers.entries) {
    if (entry.key.toLowerCase() == name) return entry.value.trim();
  }
  return null;
}

/// The one human message for a rate limit (issue #867): plan, server-derived
/// reset time in human units, and the next step — never the raw payload.
///
/// [localeCode] selects the `ru`/`en` wording (`xx_YY` codes match on the
/// language subtag). [now] is injectable for tests; the countdown prefers
/// [RateLimitInfo.resetsInSeconds] (server truth) over any wall-clock math,
/// so device clock skew cannot lie.
String formatRateLimitMessage(
  RateLimitInfo info, {
  String localeCode = 'en',
  DateTime? now,
}) {
  final ru = localeCode.toLowerCase().startsWith('ru');
  final buffer = StringBuffer(_rateLimitTitle(info, ru));
  final stamp = info.resetsAt == null
      ? null
      : formatResetStamp(info.resetsAt!.toLocal(), localeCode: localeCode);
  final countdown = _resetCountdown(info, now);
  if (stamp != null) {
    buffer.write(' ${ru ? 'Обновится' : 'Resets'} $stamp');
    if (countdown != null) {
      buffer.write(
        ' — ${formatHumanCountdown(countdown, localeCode: localeCode)}',
      );
    }
    buffer.write('.');
  } else if (countdown != null) {
    final phrase = formatHumanCountdown(countdown, localeCode: localeCode);
    buffer.write(' ${ru ? 'Повтор' : 'Try again'} $phrase.');
  } else {
    buffer.write(' ${ru ? 'Попробуйте позже.' : 'Try again later.'}');
  }
  if (info.eligiblePromo case final promo? when promo.isNotEmpty) {
    buffer.write(' ${ru ? 'Доступно промо' : 'Promo available'}: $promo.');
  }
  // OQ1 (lean yes): one next-step line, mirroring the compaction-failure
  // hint — say what unblocks the user instead of leaving them stuck.
  buffer.write('\n');
  buffer.write(
    ru
        ? 'Далее: переключитесь на модель или провайдера со свободной квотой '
              '(/model в CLI или настройки провайдера в приложении).'
        : 'Next: switch to a model or provider with available quota '
              '(/model in the CLI, or provider settings in the app).',
  );
  return buffer.toString();
}

/// Countdown for the reset: server-derived values only ([E2] clock-skew
/// safety); `Retry-After` counts only when no reset time was advertised.
Duration? _resetCountdown(RateLimitInfo info, DateTime? now) {
  final seconds = info.resetsInSeconds;
  if (seconds != null && seconds > 0) return Duration(seconds: seconds);
  final resetsAt = info.resetsAt;
  if (resetsAt != null) {
    final delta = resetsAt.difference(now ?? DateTime.now());
    return delta.isNegative ? null : delta;
  }
  final retry = info.retryAfter;
