  /// same dim transcript line + fa.log entry as the image drops.
  void _wireOperativePinNotice() {
    operativePinNotice = (notice) {
      io.writeln(_style.dim('[skills] $notice'));
      _logDiagnostic('operative pin sid=$_logSid $notice');
    };
