      session
          .appendCustomEntry(
            customType: rateLimitRetryRecordType,
            data: {
              'attempt': attempt + 1,
              'max_attempts': maxAttempts,
              'delay_ms': delay.inMilliseconds,
              'reason': reason,
              'ts': DateTime.now().toIso8601String(),
            },
          )
          .then((_) {})
          .catchError((Object error) {
            _logDiagnostic(
              '429_retry persist failed sid=$_logSid: $error',
