      io.writeln(
        _style.dim(
          '[images] dropping [Image $index] (key $keyPreview…) '
          '— per-request cap reached',
        ),
      );
      _logDiagnostic(
        'image registry drop sid=$_logSid index=$index key=$keyPreview',
      );
    };
  }

