      return false;
    }
  }
  return _pauseBetweenAttempts(
    out,
    model,
    failure.error,
    resume,
    cancelToken,
    wait,
    maxAttempts + maxRateLimitRetries,
    _shortReason(failure.error.errorMessage),
  );
