      expect(isRateLimitError(errorMsg('429 too many requests')), isTrue);
      expect(isRateLimitError(errorMsg('Provider is throttling requests')),
          isTrue);
    });

    test('budget/spending exhaustion is terminal, never a retry (issue #926)',
        () {
