      expect(isBudgetExhaustion(errorMsg('Error: 429 insufficient_quota')),
          isTrue);
    });

    test('non-error messages never classify', () {
      expect(
        isRateLimitError(
          AssistantMessage(
            content: const [],
            api: 'test-api',
            provider: 'p',
            model: 'm',
            usage: Usage.zero,
            stopReason: StopReason.stop,
            errorMessage: '429 rate limit',
            timestamp: DateTime.utc(2026),
