                '(attempt ${attempt + 1}/$maxAttempts)';
      io.writeln(_style.dim('[net] connection lost ($reason)$retryTail'));
      _logDiagnostic(
        'transient retry sid=$_logSid attempt=${attempt + 1}/$maxAttempts '
        'reason=$reason',
      );
