      _logDiagnostic(
        'transient retry sid=$_logSid attempt=${attempt + 1}/$maxAttempts '
        'reason=$reason',
      );
      if (rateLimited) {
        _recordRateLimitRetry(attempt, maxAttempts, delay, reason);
      }
