  /// retry the ladder announced. Best-effort — a persist failure never
  /// takes the run down (the task-ledger convention); the fa.log entry
  /// above already carries the facts.
  void _recordRateLimitRetry(
    int attempt,
    int maxAttempts,
    Duration delay,
    String reason,
