import 'package:test/test.dart';

import '../cli/agent_cli_test_support.dart';

AssistantMessageEventStream failWith(
  String text, {
  Duration? retryAfter,
}) {
  final stream = AssistantMessageEventStream();
  scheduleMicrotask(() {
    stream.push(
      ErrorEvent(
        reason: StopReason.error,
        retryAfter: retryAfter,
        error: AssistantMessage(
          content: const [],
          api: 'test-api',
          provider: 'test-provider',
          model: 'test-model',
          usage: Usage.zero,
          stopReason: StopReason.error,
          errorMessage: text,
          timestamp: DateTime.utc(2026),
        ),
      ),
    );
    stream.end();
  });
  return stream;
}

void main() {
  late Future<bool> Function(Duration, CancelToken?) savedSleeper;
  late TransientRetryNotice? savedNotice;
  late double Function() savedJitter;
  late Duration? Function()? savedDeadlineLeft;
